WITH metrics AS (SELECT id, channel, starts_on, discount_pct, PERCENT_RANK() OVER (PARTITION BY channel ORDER BY discount_pct DESC) AS discount_pct_percent_rank, FIRST_VALUE(channel) IGNORE NULLS OVER (PARTITION BY channel ORDER BY ends_on, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_channel FROM promotions WHERE ends_on >= '2024-04-01') SELECT id, starts_on, discount_pct, discount_pct_percent_rank, first_known_channel FROM metrics ORDER BY discount_pct_percent_rank DESC NULLS LAST
